L["guide.welcome.title"] = "第一位伙伴"
L["guide.welcome.intro"] = "恭喜！{name}成为了你的第一位伙伴。\n从今天起，你们就是一起闯荡艾泽拉斯的同伴了。"
L["guide.welcome.real.title"] = "和真正的冒险者一样"
L["guide.welcome.real.text"] = "他就像艾泽拉斯里真正的冒险者一样：施法要备材料，吃喝要自己买，装备磨损了要找铁匠修理，连花销都得自己挣。他的每一分成长，都靠你们并肩挣来。"
L["guide.welcome.grow.title"] = "和你一起成长"
L["guide.welcome.grow.text"] = "他跟着你升级、做任务、下地下城。你们分开的时候，他也有自己的日子要过。"
L["guide.welcome.person.title"] = "有自己的性格"
L["guide.welcome.person.text"] = "每位伙伴脾气不同，会和你聊天，也会在需要的时候请你帮忙。有话想说，也可以找他交谈。"
L["guide.welcome.foot"] = "点击屏幕下方的「伙伴」按钮，看看你的伙伴。"
